def rich(s):return re.sub(r'\[([^]]+)\]\(([^)]+)\)',lambda m:f'<a href="{E(m[2])}">{m[1]}</a>',E(s))
def body(text):
 out=''
 for i,section in enumerate(text.strip().split('## ')[1:],1):
  lines=section.split('\n');out+='<h2 id="section-'+str(i)+'">'+E(lines[0])+'</h2>';j=1
  while j<len(lines):
   line=lines[j]
   if line.startswith('|'):
    rows=[]
    while j<len(lines) and lines[j].startswith('|'):
     rows.append([v.strip()for v in lines[j].strip('|').split('|')]);j+=1
    out+='<div class="table-wrap"><table><caption>'+E(lines[0])+'</caption><thead><tr>'+''.join('<th scope="col">'+rich(v)+'</th>'for v in rows[0])+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+rich(v)+'</td>'for v in row)+'</tr>'for row in rows[1:])+'</tbody></table></div>'
   else:
    if line.strip():out+='<p>'+rich(line)+'</p>'
    j+=1
 return out
