labels={'name':'Plan name (max 100 characters)','objective':'One objective (max 1,000 characters)','owner':'Plan owner (max 100 characters)','start':'Plan start date','end':'Plan end date','asof':'Review date within plan period','unit':'Metric unit (max 40 characters)','method':'Measurement definition, source and comparison periods (max 1,000 characters)','baseline':'Baseline whole value (0–1,000,000)','target':'Target whole value, different from baseline (0–1,000,000)','current':'Current whole value (0–1,000,000)','capacity':'Total available whole minutes (0–1,000,000)','budget':'Total allocated-plan budget (USD, max $1,000,000)'}
fields=''
for k,l in labels.items():
 if k in ['objective','method']:control=f'<textarea id="s6-{k}" maxlength="1000" required></textarea>'
